def links_to_attachments(apps, schema_editor):
    """Each ExternalLink becomes a "link" attachment; ids, labels and
    creation times carry over."""
    ExternalLink = apps.get_model("boards", "ExternalLink")
    Attachment = apps.get_model("boards", "Attachment")
    positions = {}
    for link in ExternalLink.objects.order_by("created_at"):
        positions[link.task_id] = positions.get(link.task_id, 0) + 1024.0
        attachment = Attachment.objects.create(
            id=link.id, task_id=link.task_id, kind="link", label=link.label,
            data={"url": link.url, "provider": link.provider},
            position=positions[link.task_id],
        )
        # auto_now_add ignores the value on create; set it afterwards.
        Attachment.objects.filter(pk=attachment.pk).update(created_at=link.created_at)


def attachments_to_links(apps, schema_editor):
    ExternalLink = apps.get_model("boards", "ExternalLink")
    Attachment = apps.get_model("boards", "Attachment")
    for a in Attachment.objects.filter(kind="link", archived_at__isnull=True):
        link = ExternalLink.objects.create(
            id=a.id, task_id=a.task_id, url=a.data.get("url", ""),
            provider=a.data.get("provider") or "url", label=a.label,
        )
        ExternalLink.objects.filter(pk=link.pk).update(created_at=a.created_at)


